import pandas as pd
import numpy as np

def clean(df):
    d = df.copy()
    d = d.drop_duplicates()

    for c in ['penguin_id', 'species', 'island', 'sex']:
        if c in d.columns:
            d[c] = d[c].astype('string').str.strip()

    if 'sex' in d.columns:
        d['sex'] = d['sex'].str.lower()

    for c in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'year']:
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors='coerce')

    if 'body_mass_g' in d.columns:
        def parse_mass(x):
            if pd.isna(x):
                return np.nan
            if isinstance(x, str):
                x = x.replace(',', '').strip()
            try:
                v = float(x)
            except Exception:
                return np.nan
            if v > 6500:
                v2 = v / 1000.0
                if 2500 <= v2 <= 6500:
                    v = v2
            return v

        d['body_mass_g'] = d['body_mass_g'].map(parse_mass)

    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['sex', 'body_mass_g'])
    out = d.groupby('sex')['body_mass_g'].mean().to_dict()
    return {str(k): float(v) for k, v in out.items()}
